// Command yamlprobe checks two edge cases of the hash-truncation check:
// whether Unmarshal-into-Node fails on a multi-document stream, and
// whether a flow mapping's scalars carry the discarded comment.
package main

import (
	"fmt"

	"gopkg.in/yaml.v3"
)

const multiDoc = `author: bwk
---
author: rmh
`

const flow = `evidence: [{name: PR #515 merged, status: pass}]
`

func walk(n *yaml.Node, depth int) {
	fmt.Printf("%*skind=%d style=%d line=%d value=%q line_comment=%q\n",
		depth*2, "", n.Kind, n.Style, n.Line, n.Value, n.LineComment)
	for _, c := range n.Content {
		walk(c, depth+1)
	}
}

func main() {
	var doc yaml.Node
	err := yaml.Unmarshal([]byte(multiDoc), &doc)
	fmt.Printf("multi-document Unmarshal error: %v\n", err)

	var f yaml.Node
	if err := yaml.Unmarshal([]byte(flow), &f); err != nil {
		fmt.Println("flow unmarshal:", err)
		return
	}
	walk(&f, 0)
}

